import{_ as e,o as l,c as a,a0 as o}from"./chunks/framework.BFLrGO6w.js";const f=JSON.parse('{"title":"FFLogs 數據驗證與 rDPS 跟進計畫","description":"","frontmatter":{},"headers":[],"relativePath":"fflogs-rdps-validation-plan.md","filePath":"fflogs-rdps-validation-plan.md"}'),t={name:"fflogs-rdps-validation-plan.md"};function d(c,i,s,r,n,u){return l(),a("div",null,[...i[0]||(i[0]=[o(`<h1 id="fflogs-數據驗證與-rdps-跟進計畫" tabindex="-1">FFLogs 數據驗證與 rDPS 跟進計畫 <a class="header-anchor" href="#fflogs-數據驗證與-rdps-跟進計畫" aria-label="Permalink to &quot;FFLogs 數據驗證與 rDPS 跟進計畫&quot;">​</a></h1><p>Status: Partial</p><p>目標：讓本機 analyzer 可以逐步接近 FFLogs 的可驗證口徑。短期維持 <code>rDPS*</code> 標示；只有在對帳案例穩定通過後，才考慮調整 UI 文案。</p><h2 id="原則" tabindex="-1">原則 <a class="header-anchor" href="#原則" aria-label="Permalink to &quot;原則&quot;">​</a></h2><ul><li>以同一份 ACT log 對同一個 FFLogs fight 做對帳，不用不同場次或人工目測判斷。</li><li>先做可重跑的 baseline compare，再調整公式。</li><li>每個會影響輸出的公式改動都要 bump <code>parserVersion</code>，並重新 <code>npm run parse</code>。</li><li>對帳未通過前，UI 保持 <code>rDPS*</code> 與低/中信心標示。</li><li>連環計屬於目標 debuff，不是玩家身上的 party buff；rDPS attribution 必須支援這種套用方向。</li></ul><h2 id="現況" tabindex="-1">現況 <a class="header-anchor" href="#現況" aria-label="Permalink to &quot;現況&quot;">​</a></h2><p>已完成：</p><ul><li><code>npm run validate:data</code>：檢查 generated pull / timeline 的內部加總一致性。</li><li><code>npm run compare:fflogs</code>：已有 FFLogs 對帳殼，可以讀 <code>fflogs/cases.json</code> 與 <code>fflogs/baselines/</code>。</li><li>已有 1 個可重跑的 damage／healing／rDPS baseline：<code>XDt7a138MhLqNbkx / fight=last</code> 對本機 pull 14。加入 Damage、DPS、rDPS 欄位前，parserVersion 54 為 <code>differences=59</code>；加入後為 <code>compared=1, differences=84, invalid=0</code>，新增差異來自比較範圍擴大，不是 parser 回歸。</li><li>技能軸 M2：timeline JSON 已輸出 raw player action 對技能軸可視事件的 <code>castReconciliation</code>。</li><li>Raid buff metadata 已收錄第一批：占卜、戰鬥連禱、連環計、技巧舞步結束、灼熱之光、鼓勵、義結金蘭：攻擊。</li></ul><p>主要缺口：</p><ul><li>現有案例已可驗證 Damage、DPS、<code>rDPS*</code> 與 healing／absorbs，但仍只有單一場次；Buff Given/Taken 與 Crit/DH attribution 尚無可靠 baseline 數字。</li><li>FFLogs baseline schema 與 comparator 已支援選填的 <code>rdps</code>、Buff Given/Taken/Net、Crit/DH/CDH rate 與 <code>raidBuffContributions</code>；沒有來源的選填欄位仍保持空白，不以本機估算值回填。</li><li>倍率型 buff 分攤目前用線性權重，FFLogs 使用 log-weight。</li><li>Crit / Direct Hit buff 目前用固定期望倍率，FFLogs 使用事件 crit/DH portion 與玩家 unbuffed/buffed crit/DH 機率。</li><li>連環計是套在敵人的 debuff；目前 rDPS matching 主要用「buff target 是傷害來源玩家」的模型，需支援 target debuff。</li><li>DoT tick 已有 snapshot offset，但還沒有明確 <code>direct</code> / <code>dot</code> event kind，無法套 FFLogs 的 DoT crit/DH 公式。</li></ul><h2 id="m1-對帳基礎擴充" tabindex="-1">M1. 對帳基礎擴充 <a class="header-anchor" href="#m1-對帳基礎擴充" aria-label="Permalink to &quot;M1. 對帳基礎擴充&quot;">​</a></h2><p>Status: Done</p><p>目標：先讓 FFLogs compare 可以比到 <code>rDPS*</code> 相關欄位。</p><ul><li>[x] 擴充 <code>fflogs/baselines/*.json</code> schema： <ul><li>player <code>rdps</code></li><li>player <code>buffGiven</code></li><li>player <code>buffTaken</code></li><li>player <code>buffNet</code></li><li>player <code>critRate</code></li><li>player <code>directRate</code></li><li>player <code>critDirectRate</code></li><li>optional <code>raidBuffContributions</code></li></ul></li><li>[x] 擴充 <code>comparePullWithFflogs()</code>： <ul><li>比對 FFLogs player <code>rdps</code> 與本機 <code>estimatedRdps</code></li><li>比對 <code>raidBuffGiven</code> / <code>raidBuffTaken</code> / <code>raidBuffNet</code></li><li>比對 crit / direct / crit-direct rate</li></ul></li><li>[x] 為每個欄位設定容忍誤差： <ul><li>duration: <code>0.1s</code></li><li>DPS / HPS / rDPS: <code>0.1</code></li><li>damage / healing / buff contribution: 初期 <code>1</code>，若 FFLogs 四捨五入口徑不同再調整</li><li>rate: <code>0.1%</code></li></ul></li><li>[x] 文件更新 <code>doc/fflogs-reconciliation.md</code>，列出新 baseline 欄位。</li></ul><p><code>XDt7a138MhLqNbkx / fight=last</code> 已由既有權威 Damage Done 表補入 8 位玩家的精確 Damage、DPS、rDPS；Buff Given/Taken 與 Crit/DH 沒有現成來源，因此選填欄位保持空白，不以本機推估值冒充 FFLogs 數字。</p><p>驗收：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> parse</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate:data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compare:fflogs</span></span></code></pre></div><p>在至少 1 筆手動 baseline 下，compare 能列出 <code>rDPS*</code> 差異，而不是只比 DPS / HPS。</p><h2 id="m2-倍率型-buff-改成-fflogs-log-weight" tabindex="-1">M2. 倍率型 Buff 改成 FFLogs Log-Weight <a class="header-anchor" href="#m2-倍率型-buff-改成-fflogs-log-weight" aria-label="Permalink to &quot;M2. 倍率型 Buff 改成 FFLogs Log-Weight&quot;">​</a></h2><p>Status: Planned</p><p>目標：先讓占卜、技巧舞步結束、灼熱之光、鼓勵、義結金蘭這類倍率 buff 的分攤方式接近 FFLogs。</p><p>目前策略：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extra = actual - actual / totalMultiplier</span></span>
<span class="line"><span>share_i = extra * ((m_i - 1) / sum(m_i - 1))</span></span></code></pre></div><p>目標策略：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>M = product(m_i)</span></span>
<span class="line"><span>lost = actual - actual / M</span></span>
<span class="line"><span>share_i = lost * (log(m_i) / log(M))</span></span></code></pre></div><ul><li>[ ] 將 <code>splitEstimatedExtraDamage()</code> 改成 log-weight。</li><li>[ ] 保留單元測試案例： <ul><li>單一 10% buff。</li><li>兩個 10% buff。</li><li>5% + 6% buff。</li></ul></li><li>[ ] 更新 <code>doc/formulas-qa.md</code> 與 <code>doc/fflogs-formula-reference.md</code> 的本機公式。</li><li>[ ] bump <code>parserVersion</code>。</li></ul><p>驗收：</p><ul><li>單一 buff 的結果不變。</li><li>多 buff 疊加時，分攤符合 FFLogs help 的 log-weight 公式。</li><li><code>npm run validate:data</code> 通過。</li></ul><h2 id="m3-支援-target-debuff-型-raid-buff" tabindex="-1">M3. 支援 Target Debuff 型 Raid Buff <a class="header-anchor" href="#m3-支援-target-debuff-型-raid-buff" aria-label="Permalink to &quot;M3. 支援 Target Debuff 型 Raid Buff&quot;">​</a></h2><p>Status: Planned</p><p>目標：讓連環計這類「套在敵人身上、讓打該敵人的玩家受益」的 buff 能被 rDPS attribution 捕捉。</p><ul><li>[ ] 擴充 <code>BuffMetadata</code>： <ul><li><code>application: &#39;sourceBuff&#39; | &#39;targetDebuff&#39;</code></li></ul></li><li>[ ] 現有 party buff metadata 標成 <code>sourceBuff</code>。</li><li>[ ] 連環計標成 <code>targetDebuff</code>。</li><li>[ ] rDPS matching 改為依 application 判斷： <ul><li><code>sourceBuff</code>: <code>buff.targetId === damage.sourceId</code></li><li><code>targetDebuff</code>: <code>buff.targetId === damage.targetId</code></li></ul></li><li>[ ] Raid buff contribution table 顯示模型仍可沿用，但 tooltip 要說明 target debuff 已納入。</li><li>[ ] bump <code>parserVersion</code>。</li></ul><p>驗收：</p><ul><li>含學者的本機 log 中，連環計期間打同一目標的隊友傷害會被列入 attributed events。</li><li>沒有學者或沒有連環計 status 的 pull，不應新增連環計 contribution。</li><li><code>npm run validate:data</code> 通過。</li></ul><h2 id="m4-crit-direct-hit-buff-公式第一版" tabindex="-1">M4. Crit / Direct Hit Buff 公式第一版 <a class="header-anchor" href="#m4-crit-direct-hit-buff-公式第一版" aria-label="Permalink to &quot;M4. Crit / Direct Hit Buff 公式第一版&quot;">​</a></h2><p>Status: Planned</p><p>目標：取代目前固定期望倍率，讓連環計 / 戰鬥連禱開始接近 FFLogs 的 crit buff attribution。</p><p>FFLogs 口徑摘要：</p><ul><li>倍率 buff 先從實際傷害中取走 percentage buff 的 share。</li><li>Crit / DH buff 再對剩餘傷害 <code>N&#39;</code> 計算 crit portion / direct hit portion。</li><li>一般直接傷害依事件是否 crit / direct hit 計算。</li><li>DoT tick 使用 simulated tick 公式，不能和一般直接傷害共用同一套。</li></ul><p>第一版本機策略：</p><ul><li>[ ] 從本場觀測資料估算每位玩家的 unbuffed crit rate / direct rate。</li><li>[ ] 將 active <code>critRateBonus</code> / <code>directRateBonus</code> 納入 buffed rate。</li><li>[ ] 對直接傷害事件： <ul><li>非 crit 事件不分配 crit buff 貢獻。</li><li>crit 事件依 FFLogs help 的 crit portion 公式分配。</li><li>direct hit 同理。</li></ul></li><li>[ ] 對 DoT tick： <ul><li>先標成 low confidence。</li><li>若缺少足夠資料，維持保守估算或暫不分配，不能混成 direct event。</li></ul></li><li>[ ] 將 <code>RaidBuffAttributionModel</code> 擴充成可區分 <code>critDirectFormula</code>。</li><li>[ ] bump <code>parserVersion</code>。</li></ul><p>驗收：</p><ul><li>連環計不再以固定 <code>1.05</code> 近似處理。</li><li><code>rDPS*</code> 信心仍標示為 low，直到 FFLogs baseline 差距穩定。</li><li>有連環計的案例可在 <code>compare:fflogs</code> 看出差距縮小。</li></ul><h2 id="m5-damage-event-kind-與-dot-snapshot-完整化" tabindex="-1">M5. Damage Event Kind 與 DoT Snapshot 完整化 <a class="header-anchor" href="#m5-damage-event-kind-與-dot-snapshot-完整化" aria-label="Permalink to &quot;M5. Damage Event Kind 與 DoT Snapshot 完整化&quot;">​</a></h2><p>Status: Planned</p><p>目標：讓 DoT tick 可以套獨立公式，並避免 crit/DH rate 被 DoT tick 混淆。</p><ul><li>[ ] 擴充 <code>DamageDoneEvent</code>： <ul><li><code>eventKind: &#39;direct&#39; | &#39;dot&#39;</code></li><li><code>snapshotOffsetSeconds</code> 保留給 DoT。</li></ul></li><li>[ ] line 21 / 22 action damage 設為 <code>direct</code>。</li><li>[ ] line 24 DoT tick 設為 <code>dot</code>。</li><li>[ ] UI tooltip 更新：DoT tick crit/DH 若仍不足，需明確標示限制。</li><li>[ ] <code>validate:data</code> 增加基本檢查： <ul><li>有 <code>snapshotOffsetSeconds</code> 的事件必須是 <code>dot</code>。</li><li><code>direct</code> event 不應有 snapshot offset。</li></ul></li><li>[ ] bump <code>parserVersion</code>。</li></ul><p>驗收：</p><ul><li>DoT-heavy job 的 crit/DH 顯示限制被清楚標示。</li><li>rDPS attribution 可分支處理 direct / dot。</li></ul><h2 id="m6-fflogs-案例集" tabindex="-1">M6. FFLogs 案例集 <a class="header-anchor" href="#m6-fflogs-案例集" aria-label="Permalink to &quot;M6. FFLogs 案例集&quot;">​</a></h2><p>Status: Partial</p><p>目標：建立最小但有代表性的對照組。</p><p>目前已有 <code>XDt7a138MhLqNbkx / fight=last</code> 的 Damage、DPS、rDPS 與 healing baseline，但仍需其他組成案例。</p><ul><li>[ ] 至少 1 場無學者、倍率 buff 較單純的案例。</li><li>[ ] 至少 1 場有學者連環計的案例。</li><li>[ ] 至少 1 場多 raid buff 重疊的案例。</li><li>[ ] 至少 1 場 DoT-heavy job 明顯的案例。</li><li>[ ] 每個案例記錄： <ul><li>FFLogs URL</li><li>local ACT log</li><li>fight id</li><li>local pull id 或自動配對結果</li><li>目前差異摘要</li></ul></li></ul><p>驗收：</p><ul><li><code>npm run compare:fflogs</code> 至少 <code>compared &gt;= 3</code>。</li><li>每次 rDPS 公式變更後，都能看到差距變大或變小。</li></ul><h2 id="m7-ci-回歸保護" tabindex="-1">M7. CI / 回歸保護 <a class="header-anchor" href="#m7-ci-回歸保護" aria-label="Permalink to &quot;M7. CI / 回歸保護&quot;">​</a></h2><p>Status: Planned</p><p>目標：避免後續 UI 或 parser 調整讓數據悄悄退化。</p><ul><li>[ ] 將 <code>npm run validate:data</code> 作為固定檢查。</li><li>[ ] 有 baseline 後，將 <code>npm run compare:fflogs</code> 作為可選檢查。</li><li>[ ] <code>validate:data</code> 增加： <ul><li><code>castReconciliation.coveragePercent</code> 不可缺。</li><li><code>missingTimelineCount</code> 若大於 0，需要明確列出原因。</li><li><code>raidBuffContributions</code> 的 buff given / taken 不可為負。</li></ul></li><li>[ ] 文件列出哪些指標允許誤差、哪些應該完全一致。</li></ul><h2 id="建議執行順序" tabindex="-1">建議執行順序 <a class="header-anchor" href="#建議執行順序" aria-label="Permalink to &quot;建議執行順序&quot;">​</a></h2><ol><li>M2：倍率 buff 改 log-weight，風險低、收益明確。</li><li>M3：支援 target debuff，讓連環計真正進入 attribution。</li><li>M6：補至少一份含連環計的對照案例。</li><li>M4：正式處理 Crit / DH buff 公式。</li><li>M5：補 DoT event kind 與 simulated tick 分支。</li><li>M7：把驗證固定化。</li></ol><h2 id="暫不做" tabindex="-1">暫不做 <a class="header-anchor" href="#暫不做" aria-label="Permalink to &quot;暫不做&quot;">​</a></h2><ul><li>不串 FFLogs 帳號 OAuth，不要求使用者註冊或公開資料。</li><li>不做全站 percentile / parse rank。</li><li>不把 <code>rDPS*</code> 改名成正式 <code>rDPS</code>，直到 FFLogs 對帳案例穩定通過。</li></ul>`,64)])])}const h=e(t,[["render",d]]);export{f as __pageData,h as default};
